import React from 'react';
import Header from './components/Header';
import SmileApp from './components/SmileApp';
import Footer from './components/Footer';
import { ThemeProvider } from './contexts/ThemeContext';

function App() {
    return (
        <ThemeProvider>
            <div className="app">
                <Header />
                <SmileApp />
                <Footer />
            </div>
        </ThemeProvider>
    );
}

export default App;
